create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, email text, created_at timestamptz default now());
create table public.swing_uploads(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, video_path text not null, camera_angle text not null check(camera_angle in ('down-the-line','face-on')), club text not null, shot_result text default 'Unknown', ball_flight text, notes text, processing_status text not null default 'uploaded', processing_error text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.extracted_frames(id uuid primary key default gen_random_uuid(), swing_id uuid not null references public.swing_uploads(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, image_path text not null, frame_label text not null, approximate_time_seconds numeric, sort_order int not null, created_at timestamptz default now());
create table public.analyses(id uuid primary key default gen_random_uuid(), swing_id uuid not null references public.swing_uploads(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, model_name text not null, prompt_version text not null, structured_result jsonb not null, created_at timestamptz default now());
create table public.comparison_reports(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, previous_swing_id uuid not null references public.swing_uploads(id) on delete cascade, current_swing_id uuid not null references public.swing_uploads(id) on delete cascade, structured_result jsonb not null, model_name text not null, created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.swing_uploads enable row level security; alter table public.extracted_frames enable row level security; alter table public.analyses enable row level security; alter table public.comparison_reports enable row level security;
create policy "own profile" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "own swings" on public.swing_uploads for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own frames" on public.extracted_frames for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own analyses" on public.analyses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own comparisons" on public.comparison_reports for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('swing-media','swing-media',false,104857600,array['video/mp4','video/quicktime','video/webm','image/jpeg','image/png']) on conflict(id) do nothing;
create policy "users read own media" on storage.objects for select using(bucket_id='swing-media' and auth.uid()::text=(storage.foldername(name))[1]);
create policy "users upload own media" on storage.objects for insert with check(bucket_id='swing-media' and auth.uid()::text=(storage.foldername(name))[1]);
create policy "users delete own media" on storage.objects for delete using(bucket_id='swing-media' and auth.uid()::text=(storage.foldername(name))[1]);
